local H=game:GetService("HttpService") H.HttpEnabled=true
local B="https://raw.githubusercontent.com/gstn458/Almateh/claude/sweet-wright-wvpkpu/TeamPrincipalGame/"
local RS,SSS=game:GetService("ReplicatedStorage"),game:GetService("ServerScriptService")
local SPS=game:GetService("StarterPlayer"):WaitForChild("StarterPlayerScripts")
local function F(p,n) local f=p:FindFirstChild(n) if not f then f=Instance.new("Folder") f.Name=n f.Parent=p end return f end
local w=RS:FindFirstChild("ServerModules") if w then w:Destroy() end
local sh,cl,sv=F(RS,"Shared"),F(RS,"ClientModules"),F(SSS,"ServerModules")
local L={{"Config","ModuleScript",sh,"ReplicatedStorage/Shared/"},{"Tracks","ModuleScript",sh,"ReplicatedStorage/Shared/"},{"TrackPath","ModuleScript",sh,"ReplicatedStorage/Shared/"},{"DataManager","ModuleScript",sv,"ServerScriptService/ServerModules/"},{"TeamManager","ModuleScript",sv,"ServerScriptService/ServerModules/"},{"Weather","ModuleScript",sv,"ServerScriptService/ServerModules/"},{"TyreModel","ModuleScript",sv,"ServerScriptService/ServerModules/"},{"Radio","ModuleScript",sv,"ServerScriptService/ServerModules/"},{"RaceSim","ModuleScript",sv,"ServerScriptService/ServerModules/"},{"Objectives","ModuleScript",sv,"ServerScriptService/ServerModules/"},{"Records","ModuleScript",sv,"ServerScriptService/ServerModules/"},{"WeekendManager","ModuleScript",sv,"ServerScriptService/ServerModules/"},{"GameServer","Script",SSS,"ServerScriptService/"},{"UIKit","ModuleScript",cl,"ReplicatedStorage/ClientModules/"},{"TrackBuilder","ModuleScript",cl,"ReplicatedStorage/ClientModules/"},{"RaceViewer","ModuleScript",cl,"ReplicatedStorage/ClientModules/"},{"DriveController","ModuleScript",cl,"ReplicatedStorage/ClientModules/"},{"HubPanels","ModuleScript",cl,"ReplicatedStorage/ClientModules/"},{"HubUI","ModuleScript",cl,"ReplicatedStorage/ClientModules/"},{"PodiumScene","ModuleScript",cl,"ReplicatedStorage/ClientModules/"},{"RaceUI","ModuleScript",cl,"ReplicatedStorage/ClientModules/"},{"ClientMain","LocalScript",SPS,"StarterPlayerScripts/"}}
local n=0 for _,f in ipairs(L) do local o=f[3]:FindFirstChild(f[1]) if o then o:Destroy() end local ok,src=pcall(H.GetAsync,H,B..f[4]..f[1]..".lua",true) if ok then local s=Instance.new(f[2]) s.Name=f[1] s.Source=src s.Parent=f[3] n=n+1 print("Installed "..f[1]) else warn("FAILED "..f[1]..": "..tostring(src)) end end
print(n.." of 22 scripts installed")
